mapper.select:
SELECT DECODE(CONT_NO, '-', '신규대상', '변경대상') TARGET_TYPE ,ALANC_TYP_NM ,BIZ_CLSS_NM ,COMPANY_CODE ,COMPANY_NM ,BIZMN_REGST_NO ,DECODE(CONT_NO, '-','', CONT_NO) AS CONT_NO ,CONT_TITLE ,DECODE(TRIM(CONT_TERM), '~', '', CONT_TERM) AS CONT_TERM ,DECODE(C.STATUS, 'S','요청','T','1차심사중','C','승인','R','승인','B','반려','D','삭제') PROCE_STATE_NM ,TRTMNT_DATE ,CONT_TYPE ,FORM_NO ,ALANC_TYP_CD ,BIZ_CLSS_CD ,CNTRC_CHK FROM ( SELECT DECODE(A.BUSINESS_COND, 'B', 'C001', 'C002') AS ALANC_TYP_CD ,DECODE(A.BUSINESS_COND, 'B', '고객사', '협력사') AS ALANC_TYP_NM ,'C001' AS BIZ_CLSS_CD ,'구매대행' BIZ_CLSS_NM ,A.COM_CODE AS COMPANY_CODE ,A.COM_NAME_LOC AS COMPANY_NM ,A.IRS_NO AS BIZMN_REGST_NO ,A.CNTRC_CHK ,A.STATUS ,TO_CHAR(TO_DATE(A.CONFIRM_DATE, 'YYYY/MM/DD'), 'YYYY/MM/DD') AS TRTMNT_DATE ,B.CONT_TITLE ,NVL(B.CONT_NO, '') ||'-'|| NVL(B.CONT_COUNT, '') AS CONT_NO ,TO_CHAR(TO_DATE(B.START_DATE, 'YYYY/MM/DD'), 'YYYY/MM/DD') ||' ~ '|| TO_CHAR(TO_DATE(B.END_DATE, 'YYYY/MM/DD'), 'YYYY/MM/DD') AS CONT_TERM ,B.CONT_TYPE ,B.FORM_NO FROM ICOMCMPY A, ICOMECCT B WHERE A.COM_CODE = B.COMPANY_CODE(+) AND A.BUSINESS_COND IN ('B', 'S') AND A.STATUS <> 'D' AND A.CONFIRM_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND DECODE(LENGTH(CONT_NO), NULL, '0', '1') LIKE #{st_use_yn} || '%'
) C WHERE BIZ_CLSS_CD = #{st_biz_type}
AND ALANC_TYP_CD LIKE #{st_company_type} || '%'
AND COMPANY_CODE LIKE #{st_com_code} || '%'
AND NVL(CONT_NO, 'X') LIKE '%' || #{st_cont_no} || '%'
ORDER BY CONT_TERM, ALANC_TYP_CD, BIZ_CLSS_CD
